mapper.select:
select count(*)
from app_login_attempt
where account_hash = #{accountHash}
  and success = false
  and created_at > #{createdAt}

select count(*)
from app_login_attempt
where ip_hash = #{ipHash}
  and success = false
  and created_at > #{createdAt}

mapper.delete:
delete from app_login_attempt
where account_hash = #{accountHash}
  and success = false
